const businessHoursStart = "08:00:00Z";
const businessHoursEnd = "17:30:00Z";
const inputData = items[0].json.value;
function getDateWithTime(dateString, time) {
  const datePart = new Date(dateString).toISOString().split("T")[0];
  return new Date(`${datePart}T${time}`);
}
function getDayOfWeek(dateString) {
  const daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  return daysOfWeek[new Date(dateString).getUTCDay()];
}
function addDays(date, days) { const r = new Date(date); r.setDate(r.getDate() + days); return r; }
function formatDate(date) { return date.toISOString().split('T')[0]; }
const defaultTimeZone = inputData.length > 0 && inputData[0].start && inputData[0].start.timeZone
  ? inputData[0].start.timeZone : "UTC";
let minDate = null, maxDate = null;
inputData.forEach(event => {
  if (event.start && event.start.dateTime) {
    const d = new Date(event.start.dateTime);
    if (!minDate || d < minDate) minDate = d;
    if (!maxDate || d > maxDate) maxDate = d;
  }
});
if (minDate && maxDate) {
  minDate = new Date(minDate.toISOString().split('T')[0]);
  maxDate = new Date(maxDate.toISOString().split('T')[0]);
}
const eventsByDate = {};
inputData.forEach(event => {
  if (event.start && event.start.dateTime) {
    const k = new Date(event.start.dateTime).toISOString().split("T")[0];
    if (!eventsByDate[k]) eventsByDate[k] = [];
    if (event.showAs === "busy") {
      eventsByDate[k].push({ start: new Date(event.start.dateTime), end: new Date(event.end.dateTime), timeZone: event.start.timeZone || defaultTimeZone });
    }
  }
});
const freeTimeSlots = [];
if (minDate && maxDate) {
  for (let d = new Date(minDate); d <= maxDate; d = addDays(d, 1)) {
    const dateStr = formatDate(d);
    const busy = eventsByDate[dateStr] || [];
    const bs = getDateWithTime(dateStr, businessHoursStart);
    const be = getDateWithTime(dateStr, businessHoursEnd);
    if (busy.length === 0) {
      freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: bs.toISOString(), freeEnd: be.toISOString(), timeZone: defaultTimeZone });
      continue;
    }
    busy.sort((a, b) => a.start - b.start);
    if (busy[0].start > bs) freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: bs.toISOString(), freeEnd: busy[0].start.toISOString(), timeZone: busy[0].timeZone });
    for (let i = 0; i < busy.length - 1; i++) {
      if (busy[i].end < busy[i+1].start) freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: busy[i].end.toISOString(), freeEnd: busy[i+1].start.toISOString(), timeZone: busy[i].timeZone });
    }
    if (busy[busy.length-1].end < be) freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: busy[busy.length-1].end.toISOString(), freeEnd: be.toISOString(), timeZone: busy[busy.length-1].timeZone });
  }
}
return [{ json: { freeTimeSlots } }];

