const fs=require('fs');
const q=($('Execute Workflow Trigger').item.json.query)||{};
const cal=JSON.parse(fs.readFileSync('./calendar.json','utf8'));
const s=new Date(q.dateStartTime), e=new Date(q.dateEndTime);
if(isNaN(s)||isNaN(e)) return [{json:{booked:false,error:'bad ISO datetime'}}];
// ✅ C版示范修复①：营业时间守卫 08:00-17:30Z（模板无，A/B阶段实锤坑）
const day=s.toISOString().split('T')[0];
const bs=new Date(day+'T08:00:00Z'), be=new Date(day+'T17:30:00Z');
if(s<bs||e>be) return [{json:{booked:false,error:'outside business hours (08:00-17:30Z)'}}];
if(s.getUTCDay()===0||s.getUTCDay()===6) return [{json:{booked:false,error:'weekend not allowed'}}];
// ✅ C版示范修复②：冲突检测
const busy=(cal.events||[]).filter(x=>x.showAs==='busy').map(x=>({s:new Date(x.start.dateTime),e:new Date(x.end.dateTime),subject:x.subject}));
const clash=busy.filter(b=>s<b.e&&e>b.s);
if(clash.length) return [{json:{booked:false,error:'CONFLICT with '+clash[0].subject}}];
// 写入真日历
cal.events.push({subject:'Consultation: '+(q.name||'')+' @ '+(q.reason||''),showAs:'busy',
  start:{dateTime:s.toISOString(),timeZone:'Europe/London'},end:{dateTime:e.toISOString(),timeZone:'Europe/London'},attendee:q.email||''});
fs.writeFileSync('./calendar.json',JSON.stringify(cal,null,2));
const res=await feishuSend('【官网AI前台·新预约】\n客户: '+(q.name||'')+' ('+(q.email||'')+')\n时间: '+s.toISOString()+' ~ '+e.toISOString()+'\n事由: '+(q.reason||''));
fs_audit({type:'appointment',name:q.name||'',email:q.email||'',start:s.toISOString(),end:e.toISOString(),booked:true,notified:res.code===0});
return [{json:{booked:true,start:s.toISOString(),end:e.toISOString(),attendee:q.email||'',notified:res.code===0}}];
